import { Component, OnInit } from '@angular/core';

interface ShapeItem {
  id: string;
  name: string;
  sides: number;
  corners: number;
  icon: string;
  color: string;
  examples: string[];
}

@Component({
  selector: 'app-shapes',
  templateUrl: './shapes.component.html',
  styleUrls: ['./shapes.component.scss']
})
export class ShapesComponent implements OnInit {

  shapes: ShapeItem[] = [
    { id: 'circle', name: 'دایره', sides: 0, corners: 0, icon: '⚪️', color: '#3b82f6', examples: ['سکه', 'چرخ ماشین', 'بشقاب', 'ساعت دیواری'] },
    { id: 'triangle', name: 'مثلث', sides: 3, corners: 3, icon: '🔺', color: '#ef4444', examples: ['برش پیتزا', 'شیروانی خانه', 'کوه', 'تکه پنیر'] },
    { id: 'square', name: 'مربع', sides: 4, corners: 4, icon: '🟩', color: '#10b981', examples: ['جعبه دستمال', 'تاس بازی', 'کاشی حمام', 'قاب عکس'] },
    { id: 'rectangle', name: 'مستطیل', sides: 4, corners: 4, icon: '🚪', color: '#f59e0b', examples: ['در کلاس', 'کتاب درسی', 'تخته سیاه', 'فرش'] }
  ];

  selectedShape: ShapeItem = this.shapes[0];

  // کوئیز
  quizCurrentIndex = 0;
  quizScore = 0;
  quizAnswered = false;
  quizFeedback = '';

  ngOnInit(): void {
    this.newQuiz();
  }

  selectShape(s: ShapeItem): void {
    this.selectedShape = s;
  }

  newQuiz(): void {
    this.quizAnswered = false;
    this.quizFeedback = '';
    this.quizCurrentIndex = Math.floor(Math.random() * this.shapes.length);
  }

  answerQuiz(shapeId: string): void {
    if (this.quizAnswered) { return; }
    this.quizAnswered = true;
    if (shapeId === this.shapes[this.quizCurrentIndex].id) {
      this.quizFeedback = 'correct';
      this.quizScore += 10;
    } else {
      this.quizFeedback = 'wrong';
    }
  }
}
